	private static CatalogValues catalogValues(Value first, Value second) {
		PlanValueCatalog.Builder builder = new PlanValueCatalog.Builder();
		long firstId = UNKNOWN;
		long secondId = UNKNOWN;
		for (int i = 0; i <= SECOND_ADVERSARIAL_INDEX; i++) {
			Value value = i == ADVERSARIAL_INDEX ? first
					: i == SECOND_ADVERSARIAL_INDEX ? second : iri("plan-filler-" + i);
			long id = builder.internConstant(value);
			if (i == ADVERSARIAL_INDEX) {
				firstId = id;
			} else if (i == SECOND_ADVERSARIAL_INDEX) {
				secondId = id;
			}
		}
		return new CatalogValues(builder.build(), firstId, secondId);
	}

	private static SyntheticValueSource evaluationSource(PlanValueCatalog catalog) {
		return new SyntheticValueSource(new CodecSource(), catalog).forEvaluation();
	}

	private static RowState row(SyntheticValueSource source) {
		RowState row = new RowState(source, NativeSlotLayout.empty(), EmptyBindingSet.getInstance());
		Arrays.fill(row.slots, UNKNOWN);
		row.recomputeBoundMask();
		return row;
	}

	private static LmdbNativeKernelHooks hooks(RowState row) {
		LmdbNativeKernelBindings bindings = new LmdbNativeKernelBindings(
				new LmdbNativeKernelBindings.AdjacencyRequest[0], new long[0], new int[0],
				new LmdbNativeKernelBindings.DomainRequest[0], new LmdbNativeKernelBindings.FilterHook[0], new int[0],
				List.of());
		return new LmdbNativeKernelHooks(row, bindings);
	}

	private static void close(LmdbNativeKernelHooks hooks, RowState row, SyntheticValueSource source) {
		try {
			hooks.closeFilters();
		} finally {
			row.closeDecodedInputs();
			source.executionContext().close();
		}
	}

	private static Value iri(String suffix) {
		return VF.createIRI("urn:identity:" + suffix);
	}

